 internal static class MultiRegionChecks {
  internal static int Run(string folder){Directory.CreateDirectory(folder);Settings.IsolatedTestRoot=Path.Combine(folder,"isolated-runtime");var rows=new List<object>();var metrics=new List<object>();int failed=0;void Check(string name,Action test){var clock=Stopwatch.StartNew();try{test();rows.Add(new{name,passed=true,seconds=clock.Elapsed.TotalSeconds});}catch(Exception e){failed++;rows.Add(new{name,passed=false,error=e.ToString()});}}
   BitmapSource Sheet(){var v=new DrawingVisual();using(var d=v.RenderOpen()){d.DrawRectangle(System.Windows.Media.Brushes.White,null,new Rect(0,0,1000,1400));d.DrawRectangle(System.Windows.Media.Brushes.Red,null,new Rect(100,100,650,180));d.DrawRectangle(System.Windows.Media.Brushes.Lime,null,new Rect(100,450,650,180));d.DrawRectangle(System.Windows.Media.Brushes.Blue,null,new Rect(100,900,650,180));}var b=new RenderTargetBitmap(1000,1400,96,96,PixelFormats.Pbgra32);b.Render(v);b.Freeze();return b;}
   void Reject(Action test){try{test();}catch(InvalidOperationException){return;}throw new Exception("Expected rejection");}
   void Save(PhotoData image,string name){File.WriteAllBytes(Path.Combine(folder,name),image.Jpeg);}
   using(var workspace=new QuestionWorkspace(Settings.DataRoot)){
    var page=workspace.Add(Sheet(),"合成三题");var first=workspace.AddRegion(page.Id,new Int32Rect(100,100,650,180));var middle=workspace.AddRegion(page.Id,new Int32Rect(100,450,650,180));var last=workspace.AddRegion(page.Id,new Int32Rect(100,900,650,180));
    Check("noncontiguous regions compose without the unselected middle question",()=>{workspace.Attach(first.Id);workspace.Attach(last.Id);var payload=workspace.Compose(true,CancellationToken.None);if(payload.Images.Length!=1||!payload.Instruction.Contains("同一道题"))throw new Exception("group input");var image=new FormatConvertedBitmap(payload.Images[0].Image,PixelFormats.Bgr24,null,0);var pixels=new byte[image.PixelWidth*image.PixelHeight*3];image.CopyPixels(pixels,image.PixelWidth*3,0);for(int i=0;i<pixels.Length;i+=3)if(pixels[i+1]>220&&pixels[i]<30&&pixels[i+2]<30)throw new Exception("unselected green question leaked");Save(payload.Images[0],"两处不连续区域_无中间别题.jpg");});
    string groupOne=workspace.ActiveId;
    Check("one page three independent question groups and click identity",()=>{workspace.Attach(middle.Id,true);string second=workspace.ActiveId;workspace.Attach(last.Id,true);if(workspace.Groups.Count!=3||workspace.Active.Regions.Count!=1)throw new Exception("not independent");workspace.Select(second);if(workspace.Active.Regions.Single()!=middle.Id)throw new Exception("wrong clicked question");});
    Check("shared stem can belong to another question without duplicate references",()=>{workspace.Select(groupOne);workspace.Attach(first.Id);if(workspace.Active.Regions.Count!=2)throw new Exception("duplicate");workspace.Attach(middle.Id);workspace.Move(middle.Id,-1);if(workspace.Active.Regions[1]!=middle.Id)throw new Exception("order");workspace.Detach(middle.Id);if(workspace.Active.Regions.Count!=2||workspace.Active.Regions[1]!=last.Id)throw new Exception("delete middle");});
    Check("cross-page order is preserved including return to the first page",()=>{var p2=workspace.Add(Sheet(),"第2页");var r2=workspace.AddRegion(p2.Id,new Int32Rect(100,100,650,180));workspace.Attach(r2.Id);workspace.Move(r2.Id,-1);var payload=workspace.Compose(true,CancellationToken.None);if(payload.Images.Length!=3)throw new Exception("A-B-A page order collapsed");if(payload.Images.Select(x=>x.DataUri).Distinct().Count()<2)throw new Exception("lost page data");});
    Check("reverse selection, letterbox, zoom 25-600 percent and DPI scale",()=>{foreach(float zoom in new[]{.25f,1f,6f})foreach(int dpi in new[]{96,144,192,288}){var fit=CropGeometry.Fit(new Size(1200*dpi/96,900*dpi/96),new Size(1000,1400));var bounds=new RectangleF(fit.X-200,fit.Y+50,fit.Width*zoom,fit.Height*zoom);var rect=CropGeometry.Pixels(new RectangleF(bounds.X+bounds.Width*.75f,bounds.Y+bounds.Height*.75f,-bounds.Width*.5f,-bounds.Height*.5f),bounds,new Size(1000,1400));if(Math.Abs(rect.X-250)>1||Math.Abs(rect.Y-350)>1||Math.Abs(rect.Width-500)>2||Math.Abs(rect.Height-700)>2)throw new Exception("coordinate drift "+rect);var all=CropGeometry.Pixels(new RectangleF(bounds.X-100,bounds.Y-100,bounds.Width+200,bounds.Height+200),bounds,new Size(1000,1400));if(all.Width!=1000||all.Height!=1400)throw new Exception("clamping");}});
    Check("rotation explicitly invalidates original-coordinate regions and requires reselect",()=>{workspace.Rotate(page.Id);if(workspace.Regions.Any(r=>r.PageId==page.Id)||workspace.Groups.Any(g=>g.Regions.Contains(first.Id)))throw new Exception("old coordinates survived");if(page.Width!=1400||page.Height!=1000)throw new Exception("rotation dimensions");var r=workspace.AddRegion(page.Id,new Int32Rect(20,20,400,300));workspace.Attach(r.Id);});
    Check("asynchronous old composition cannot enter a new group",()=>{var task=workspace.ComposeAsync(true,CancellationToken.None);workspace.NewGroup();try{task.GetAwaiter().GetResult();throw new Exception("stale result accepted");}catch(OperationCanceledException){}});
    Check("dialog constructs without a model request or visible window",()=>{using(var form=new QuestionBoardDialog(workspace,true)){Entry.OfflineUiTesting=true;form.ShowInTaskbar=false;form.StartPosition=System.Windows.Forms.FormStartPosition.Manual;form.Location=new System.Drawing.Point(-12000,-12000);form.Show();System.Windows.Forms.Application.DoEvents();form.PerformLayout();using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(System.Drawing.Point.Empty,form.Size));bmp.Save(Path.Combine(folder,"多区域组题界面_离线.png"));}if(form.Result!=null)throw new Exception("auto confirmed");form.Close();Entry.OfflineUiTesting=false;}});
   }
   Check("fifty rotations are flat bitmaps with bounded retained memory",()=>{var image=PhotoData.Create(Sheet(),"合成旋转",true);GC.Collect();GC.WaitForPendingFinalizers();long before=GC.GetTotalMemory(true),privateBefore=Process.GetCurrentProcess().PrivateMemorySize64;for(int i=0;i<50;i++){image=image.Rotate(true);if(image.Image is TransformedBitmap||image.Image is CroppedBitmap)throw new Exception("retained source chain");}long after=GC.GetTotalMemory(true);metrics.Add(new{scenario="same synthetic image rotated 50 times",managedBefore=before,managedAfter=after,privateBefore,privateAfter=Process.GetCurrentProcess().PrivateMemorySize64});if(after-before>40L*1024*1024)throw new Exception("unexpected retained graph growth");});
   Check("six original pages are disk-backed; crop and restore do not retain all originals",()=>{using(var w=new QuestionWorkspace(Settings.DataRoot)){for(int i=0;i<6;i++){var p=w.Add(Sheet(),"页"+i);var r=w.AddRegion(p.Id,new Int32Rect(50,50,700,400));w.Attach(r.Id);}var composed=w.Compose(true,CancellationToken.None);if(composed.Images.Length!=6||w.Pages.Any(p=>!File.Exists(p.File)))throw new Exception("original/payload");Reject(()=>w.Add(Sheet(),"第7页"));GC.Collect();metrics.Add(new{scenario="six-page crop/restore",managed=GC.GetTotalMemory(true),privateBytes=Process.GetCurrentProcess().PrivateMemorySize64,decodedPayloadPixels=composed.Images.Sum(x=>(long)x.Image.PixelWidth*x.Image.PixelHeight),originalPixelsOnDisk=w.Pages.Sum(x=>(long)x.Width*x.Height)});foreach(var p in w.Pages){var original=p.Decode();if(original.PixelWidth!=1000||original.PixelHeight!=1400)throw new Exception("restore");}}});
   Check("demonstration camera release completes and emits no callbacks after dispose",()=>{int frames=0;using(var camera=new CameraSession("test-only",false,Sheet())){camera.Frame+=_=>Interlocked.Increment(ref frames);Thread.Sleep(300);camera.Dispose();int atDispose=frames;if(!camera.Released.Wait(2000))throw new Exception("release not completed");Thread.Sleep(180);if(frames!=atDispose||CameraSession.IsActive)throw new Exception("late callback or active graph");}});
   Check("candidate anchors retain options, separate independent questions and never create groups",()=>{var lines=new[]{new OcrLine{Text="1. First question",X=50,Y=80,Width=500,Height=30},new OcrLine{Text="A. one B. two C. three D. four",X=50,Y=150,Width=700,Height=30},new OcrLine{Text="2. Second question",X=50,Y=600,Width=500,Height=30},new OcrLine{Text="A. yes B. no",X=50,Y=700,Width=700,Height=30}};var candidates=CandidateDetector.FromLines(lines,1000,1400,2000,2800);if(candidates.Count!=2||candidates[0].Bounds.Y+candidates[0].Bounds.Height>1200||candidates[0].Bounds.Y+candidates[0].Bounds.Height<350)throw new Exception("question/option boundary");});
   Check("subquestions do not become separate questions; unnumbered pages fall back to manual",()=>{var lines=new[]{new OcrLine{Text="Read this material",X=50,Y=50,Width=800,Height=40},new OcrLine{Text="(1) Explain",X=50,Y=400,Width=500,Height=40},new OcrLine{Text="(2) Compare",X=50,Y=700,Width=500,Height=40}};if(CandidateDetector.FromLines(lines,1000,1400,1000,1400).Count!=0)throw new Exception("shared stem split");});
   Check("Windows OCR runs locally or reports manual fallback without blocking selection",()=>{using(var w=new QuestionWorkspace(Settings.DataRoot)){var p=w.Add(PrintedPage(),"合成印刷题");var result=CandidateDetector.Detect(p,CancellationToken.None).GetAwaiter().GetResult();metrics.Add(new{scenario="actual local Windows OCR on synthetic printed page",result.OcrAvailable,candidates=result.Regions.Count,result.Seconds,result.PrivateBytes,result.Message});if(result.Message.Length==0||result.Seconds>25)throw new Exception("no actionable outcome");}});
   Check("follow-up request includes exactly the confirmed group images with original order",()=>{using(var w=new QuestionWorkspace(Settings.DataRoot)){var a=w.Add(Sheet(),"合成页A");var b=w.Add(Sheet(),"合成页B");w.Attach(w.AddRegion(a.Id,new Int32Rect(100,100,650,180)).Id);w.Attach(w.AddRegion(b.Id,new Int32Rect(100,900,650,180)).Id);var payload=w.Compose(true,CancellationToken.None);using(var fake=new RequestRecorder())using(var http=new HttpClient(fake)){AiClient.SolveUsing(http,new Settings{DeepSeekApiKey="offline-test-only"},payload.Images[0],payload.Instruction+"\n追问这一步",_=>{},_=>{},CancellationToken.None,new[]{new ChatTurn("user","本题"),new ChatTurn("assistant","前文")},null,payload.Images,payload.Instruction).GetAwaiter().GetResult();var messages=(JArray)fake.Request!["messages"]!;if(!((string)messages[0]!["content"]!).Contains("教师已确认的选区约束"))throw new Exception("group instruction lost at system level");var images=((JArray)messages[1]!["content"]!).OfType<JObject>().Where(x=>(string?)x["type"]=="image_url").Select(x=>(string)x["image_url"]!["url"]!).ToArray();if(!images.SequenceEqual(payload.Images.Select(x=>x.DataUri))||fake.Count!=1)throw new Exception("lost, duplicate, reordered images or replay");}}});
   Check("late candidate callback cannot populate a new group after page rotation or group change",()=>{using(var w=new QuestionWorkspace(Settings.DataRoot)){var p=w.Add(Sheet(),"合成页");long stamp=w.Revision;int revision=p.Revision;var candidates=new[]{new RegionCandidate{Bounds=new Int32Rect(20,20,400,300),Confidence=.7}};w.NewGroup();if(w.AcceptCandidates(p.Id,revision,stamp,candidates)||w.Regions.Count>0)throw new Exception("old group callback");stamp=w.Revision;w.Rotate(p.Id);if(w.AcceptCandidates(p.Id,revision,stamp,candidates)||w.Regions.Count>0)throw new Exception("old rotated callback");}});
   Check("new conversation releases original cache and does not reuse question identity",()=>{var w=new QuestionWorkspace(Settings.DataRoot);string oldId=w.ActiveId;var p=w.Add(Sheet(),"合成页");string cache=Path.GetDirectoryName(p.File)!;w.Dispose();if(Directory.Exists(cache)||w.Pages.Count!=0||w.Regions.Count!=0)throw new Exception("cache retained");using(var next=new QuestionWorkspace(Settings.DataRoot))if(next.ActiveId==oldId||next.Regions.Count!=0)throw new Exception("question identity reused");});
   Check("per-user data paths do not select a shared F folder and encrypted legacy migration is non-destructive",()=>{if(Settings.UserDataRoot("user-a/AppData/Local")==Settings.UserDataRoot("user-b/AppData/Local"))throw new Exception("shared user root");string prior=Settings.IsolatedTestRoot!,a=Path.Combine(folder,"settings-a"),b=Path.Combine(folder,"settings-b");try{Settings.IsolatedTestRoot=a;var settings=new Settings{Provider="Doubao",DoubaoModel="offline-legacy-model"};settings.Save();string legacy=Path.Combine(a,"settings.protected");byte[] original=File.ReadAllBytes(legacy);Settings.IsolatedTestRoot=b;Settings.IsolatedLegacyPath=legacy;var loaded=Settings.Load();if(loaded.Provider!="Doubao"||loaded.DoubaoModel!="offline-legacy-model"||!File.ReadAllBytes(legacy).SequenceEqual(original)||!File.Exists(Path.Combine(b,"settings.protected")))throw new Exception("legacy migration changed original or lost config");}finally{Settings.IsolatedTestRoot=prior;Settings.IsolatedLegacyPath=null;}});
   Check("owned expired cache is pruned while unrelated files are preserved",()=>{string root=Path.Combine(folder,"prune-fixtures");var w=new QuestionWorkspace(root);var p=w.Add(Sheet(),"合成页");string cache=Path.GetDirectoryName(p.File)!;Directory.SetLastWriteTimeUtc(cache,DateTime.UtcNow.AddDays(-3));string unrelated=Path.Combine(root,"regions_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(unrelated);File.WriteAllText(Path.Combine(unrelated,"teacher-original.txt"),"keep");Directory.SetLastWriteTimeUtc(unrelated,DateTime.UtcNow.AddDays(-3));QuestionWorkspace.Prune(root);if(Directory.Exists(cache)||!File.Exists(Path.Combine(unrelated,"teacher-original.txt")))throw new Exception("cache cleanup scope");w.Dispose();});
   Check("all eight EXIF orientations preserve the expected corner identities",()=>{byte[] pixels={0,0,255,0,255,0,255,0,0,0,255,255};var source=BitmapSource.Create(2,2,96,96,PixelFormats.Bgr24,null,pixels,6);source.Freeze();string[] expected={"RGBY","GRYB","YBGR","BYRG","RBGY","BRYG","YGBR","GYRB"};string Corners(BitmapSource image){var b=new FormatConvertedBitmap(image,PixelFormats.Bgr24,null,0);var values=new byte[b.PixelWidth*b.PixelHeight*3];b.CopyPixels(values,b.PixelWidth*3,0);string result="";foreach(int index in new[]{0,b.PixelWidth-1,(b.PixelHeight-1)*b.PixelWidth,b.PixelHeight*b.PixelWidth-1}){int i=index*3;result+=values[i+2]>200?(values[i+1]>200?"Y":"R"):values[i+1]>200?"G":"B";}return result;}for(int i=1;i<=8;i++)if(Corners(PhotoOrientation.Canonical(source,i))!=expected[i-1])throw new Exception("orientation "+i+" corner mismatch");});
   Check("legacy single-region recrop uses original pixels and originalPages can keep disk-only proxies",()=>{var v=new DrawingVisual();using(var d=v.RenderOpen())d.DrawRectangle(System.Windows.Media.Brushes.White,null,new Rect(0,0,4000,1200));var wide=new RenderTargetBitmap(4000,1200,96,96,PixelFormats.Pbgra32);wide.Render(v);wide.Freeze();string source=Path.Combine(folder,"合成宽幅原图.png");var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(wide));using(var stream=File.Create(source))encoder.Save(stream);var original=PhotoData.FromFileForSelection(source);if(original.Image.PixelWidth!=4000||!original.IsSelectionSource)throw new Exception("whole page shrunk before selection");var proxies=new List<PhotoData>();try{for(int i=0;i<6;i++)proxies.Add(original.CacheOriginal());foreach(var proxy in proxies){if(typeof(PhotoData).GetField("image",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(proxy)!=null)throw new Exception("decoded original retained");var crop=proxy.Crop(new Int32Rect(100,100,500,400),false);if(crop.Image.PixelWidth!=500||crop.Image.PixelHeight!=400)throw new Exception("crop original coordinates lost");Reject(()=>{var ignored=proxy.Jpeg;});}using(var w=new QuestionWorkspace(Settings.DataRoot)){foreach(var proxy in proxies)w.CopyOriginal(proxy);if(w.Pages.Count!=6||w.Pages.Any(page=>page.Width!=4000))throw new Exception("full resolution lost during transition to region editor");}GC.Collect();metrics.Add(new{scenario="six legacy original proxies with recrop and restore",originalWidth=4000,originalHeight=1200,decodedOriginalFields=0,managedAfterGc=GC.GetTotalMemory(true),privateAfterGc=Process.GetCurrentProcess().PrivateMemorySize64});}finally{foreach(var proxy in proxies)proxy.ReleaseOriginal();}});
   Check("labels keep a separate fixed gutter and cannot overprint highly downscaled original ink",()=>{var v=new DrawingVisual();using(var d=v.RenderOpen())d.DrawRectangle(System.Windows.Media.Brushes.Red,null,new Rect(0,0,9000,600));var bitmap=new RenderTargetBitmap(9000,600,96,96,PixelFormats.Pbgra32);bitmap.Render(v);bitmap.Freeze();using(var w=new QuestionWorkspace(Settings.DataRoot)){var p=w.Add(bitmap,"合成宽幅红色原图");w.Attach(w.AddRegion(p.Id,new Int32Rect(0,0,9000,600)).Id);var result=w.Compose(false,CancellationToken.None).Images[0];var image=new FormatConvertedBitmap(result.Image,PixelFormats.Bgr24,null,0);byte[] pixels=new byte[image.PixelWidth*image.PixelHeight*3];image.CopyPixels(pixels,image.PixelWidth*3,0);int first=-1;for(int y=0;y<image.PixelHeight;y++){int i=y*image.PixelWidth*3;if(pixels[i+2]>240&&pixels[i]<20&&pixels[i+1]<20){first=y;break;}}if(first<0)throw new Exception("source absent");for(int y=first+2;y<first+8;y++)for(int x=6;x<160;x++){int i=(y*image.PixelWidth+x)*3;if(pixels[i+2]<240||pixels[i]>20||pixels[i+1]>20)throw new Exception("label overwrote original pixels");}}});
   File.WriteAllText(Path.Combine(folder,"多区域与稳定性检查.json"),JsonConvert.SerializeObject(new{failed,checks=rows,metrics,paidRequests=0,realCameraTested=false,schoolHardwareTested=false},Formatting.Indented));return failed==0?0:1;
