  internal static BitmapSource PrintedPage(){var v=new DrawingVisual();using(var d=v.RenderOpen()){d.DrawRectangle(System.Windows.Media.Brushes.White,null,new Rect(0,0,1200,1600));for(int i=0;i<3;i++){double y=80+i*460;var f=new FormattedText((i+1)+". Choose the correct answer.\nThe diagram belongs to this question.\nA. one    B. two    C. three    D. four",System.Globalization.CultureInfo.GetCultureInfo("en-US"),FlowDirection.LeftToRight,new Typeface("Arial"),34,System.Windows.Media.Brushes.Black,1){MaxTextWidth=1050,LineHeight=65};d.DrawText(f,new System.Windows.Point(60,y));d.DrawRectangle(null,new System.Windows.Media.Pen(System.Windows.Media.Brushes.Black,3),new Rect(70,y+210,250,100));}}var image=new RenderTargetBitmap(1200,1600,96,96,PixelFormats.Pbgra32);image.Render(v);image.Freeze();return image;}
